172.      *
173.      * Any existing value gets cleared.
174.      */
175.     public void set(@Nullable String text) {
176.         //if the text is longer than 255 characters, use the high throughput variant
177.         if (text!=null && text.length() > 255)
178.             setAtOnce(text);
179.         else {
180.             WebElement e = resolve();
181.             e.clear();
182.             e.sendKeys(StringUtils.defaultString(text));
